#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
size_t scale(const char *t, const char *intervals, char (*out)[3]) {
    const char *sharp[] = {"A",  "A#", "B", "C",  "C#", "D",
                           "D#", "E",  "F", "F#", "G",  "G#"},
               *flat[] = {"A",  "Bb", "B", "C",  "Db", "D",
                          "Eb", "E",  "F", "Gb", "G",  "Ab"},
               *keys[] = {"F", "Bb", "Eb", "Ab", "Db", "Gb",
                          "d", "g",  "c",  "f",  "bb", "eb"};
    bool use = false;
    for (int i = 0; i < 12; i++)
        if (!strcmp(t, keys[i]))
            use = true;
    const char *const *s = use ? flat : sharp;
    char tonic[3] = {0};
    if (strlen(t) > 2)
        return 0;
    strcpy(tonic, t);
    tonic[0] = (char)toupper((unsigned char)tonic[0]);
    int start = -1;
    for (int i = 0; i < 12; i++)
        if (!strcmp(s[i], tonic))
            start = i;
    if (start < 0)
        return 0;
    if (!intervals) {
        for (int i = 0; i < 12; i++)
            strcpy(out[i], s[(start + i) % 12]);
        return 12;
    }
    size_t n = 0;
    int index = start;
    for (const char *p = intervals; *p; p++) {
        strcpy(out[n++], s[index % 12]);
        int step = *p == 'm' ? 1 : *p == 'M' ? 2 : *p == 'A' ? 3 : 0;
        if (!step)
            return 0;
        index += step;
    }
    strcpy(out[n++], s[index % 12]);
    return n;
}

