#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}

int main(void) {
    char o[20][3];
    assert(scale("C", "MMmMMMm", o) == 8 && !strcmp(o[0], "C") && !strcmp(o[3], "F") &&
           !strcmp(o[7], "C"));
    assert(scale("F", NULL, o) == 12 && !strcmp(o[5], "Bb"));
    assert(scale("g", "MmMMmMM", o) == 8 && !strcmp(o[2], "Bb"));
    assert(scale("C", "M", o) == 2 && !strcmp(o[1], "D"));
    assert(scale("F", "m", o) == 2 && !strcmp(o[1], "Gb"));
    assert(scale("C", "", o) == 1 && !strcmp(o[0], "C"));

    return 0;
}
